# Create mapping from note_id to group_id based on title matching
note_to_group = {}
for note_id in trip_note_ids:
    note = apis.simple_note.show_note(access_token=access_token, note_id=note_id)
    title = note['title'].strip()
    # Find matching group by name (case-insensitive, strip trailing period)
    for g in groups:
        if g['name'].strip().lower() == title.lower() or g['name'].strip().lower().rstrip('.') == title.lower().rstrip('.'):
            note_to_group[note_id] = g['group_id']
            break
    else:
        print(f"No group found for note: {title} (ID: {note_id})")

print("Note to group mapping:")
for nid, gid in note_to_group.items():
    print(f"  Note {nid} -> Group {gid}")

