steps.code:
# Build mapping from group_id to member first name -> email
group_member_emails = {}
for g in groups:
    group_id = g['group_id']
    member_map = {}
    for m in g['members']:
        # Use first name as key (split on space)
        first = m['name'].split()[0]
        member_map[first] = m['email']
    group_member_emails[group_id] = member_map

# Map note_id to group_id based on title matching
note_to_group = {}
for note_id in trip_note_ids:
    note = apis.simple_note.show_note(access_token=access_token, note_id=note_id)
    title = note['title']
    # Find group with same name (case-insensitive)
    for g in groups:
        if g['name'].lower() == title.lower():
            note_to_group[note_id] = g['group_id']
            break
    else:
        # Try matching by description or partial
        for g in groups:
            if g['description'] and g['description'].lower() == title.lower():
                note_to_group[note_id] = g['group_id']
                break

print("Note to group mapping:", note_to_group)

